Write-Host "Aplicando la 1.5b en $raiz" -ForegroundColor White
$escritos = 0
foreach ($a in $archivos) {
    $destino = Join-Path $raiz $a.ruta
    $carpeta = Split-Path -Parent $destino
    if (-not (Test-Path $carpeta)) { New-Item -ItemType Directory -Path $carpeta -Force | Out-Null }
    if (Test-Path $destino) {
        Copy-Item $destino "$destino.antes-de-1-5b" -Force
    }
    $limpio = ($a.b64 -replace '\s', '')
    [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String($limpio))
    Write-Host ("  OK  " + $a.ruta) -ForegroundColor Green
    $escritos++
}
Write-Host ""
Write-Host "$escritos archivos escritos." -ForegroundColor Cyan
